#!/bin/bash
# =====================================================================
#  まよ鯖 Bot … VPS（ConoHa など・Ubuntu / Debian）に入れる
#   チケット・役職パネル・募集・モデレーションのログ・歓迎・メッセージのログ
#
#  使い方（VPS のコンソールで）:
#    curl -fsSL https://tool.m-ayosaba.com/download/mayo-bot-setup.sh | sudo bash
#  とちゅうで Discord の Bot のトークンを聞かれるので、貼って Enter（画面には出ません）。
#  何回実行しても大丈夫です（トークンとデータはそのまま残ります）。新しい版にするときも同じコマンドか sudo mayo-bot update
#
#  入る場所: /opt/mayo-bot（プログラム）・/etc/mayo-bot/env（トークン）・/var/lib/mayo-bot（データ）
#  このファイルは tools/build-setup.mjs で作っています（Bot のファイルを中に入れるため）。
#  制作: MaYo (mayo01297)  https://github.com/Dev-MaY0  二次配布禁止
# =====================================================================
set -u

main() {
ROOT="${MAYO_ROOT:-}"                                           # テスト用（ふつうは空）
NODE_DIST="${NODE_DIST:-https://nodejs.org/dist/latest-v22.x}"  # Node.js 22（LTS）の最新版
BUNDLE_SHA256="9e0fbe35ff852b60f48cfb87c5673ff8c0dc86e6426b15dfb94fbfcaa5b3b403"
BUILD="9e0fbe35ff85"
UPDATE_URL="${MAYO_BOT_URL:-https://tool.m-ayosaba.com/download/mayo-bot-setup.sh}"
APP="$ROOT/opt/mayo-bot"
ETC="$ROOT/etc/mayo-bot"
STATE="$ROOT/var/lib/mayo-bot"
SVC=mayo-bot
say() { echo "[mayo-bot] $*"; }
die() { echo "[mayo-bot] ✗ $*" >&2; exit 1; }

echo "=================================================="
echo " まよ鯖 Bot を入れます（ビルド $BUILD） 制作: MaYo / mayo01297"
echo "=================================================="
[ -n "$ROOT" ] || [ "$(id -u)" = "0" ] || die "管理者（root）で実行してください（コマンドの先頭に sudo を付ける）"
[ -n "$ROOT" ] || command -v systemctl >/dev/null 2>&1 || die "systemd が見つかりません（Ubuntu / Debian で実行してください）"
for c in curl tar sha256sum; do command -v "$c" >/dev/null 2>&1 || die "$c がありません（sudo apt-get install -y $c）"; done

# ---- 1. Node.js（公式のもの。チェックサムを確かめる）--------------------------
case "$(uname -m)" in
  x86_64) NODE_ARCH=linux-x64 ;;
  aarch64) NODE_ARCH=linux-arm64 ;;
  *) die "この CPU（$(uname -m)）には対応していません" ;;
esac
NODE="${MAYO_NODE:-$APP/node/bin/node}"
if [ -z "${MAYO_NODE:-}" ] && { [ ! -x "$NODE" ] || ! "$NODE" -v 2>/dev/null | grep -q '^v22\.'; }; then
  say "Node.js を入れています…"
  TMP="$(mktemp -d)"
  curl -fsSL -m 60 "$NODE_DIST/SHASUMS256.txt" -o "$TMP/SHASUMS256.txt" || die "Node.js の一覧を取れませんでした"
  FILE="$(grep -oE "node-v22\.[0-9]+\.[0-9]+-${NODE_ARCH}\.tar\.gz" "$TMP/SHASUMS256.txt" | head -1)"
  [ -n "$FILE" ] || die "Node.js のファイルが見つかりませんでした"
  curl -fsSL -m 600 "$NODE_DIST/$FILE" -o "$TMP/$FILE" || die "Node.js をダウンロードできませんでした"
  (cd "$TMP" && grep " $FILE\$" SHASUMS256.txt | sha256sum -c - >/dev/null) || die "Node.js のチェックサムが合いません（入れるのをやめました）"
  mkdir -p "$APP"
  rm -rf "$APP/node.new" && mkdir "$APP/node.new"
  tar -xzf "$TMP/$FILE" -C "$APP/node.new" --strip-components=1 --no-same-owner
  rm -rf "$APP/node" && mv "$APP/node.new" "$APP/node"
  rm -rf "$TMP"
fi
say "Node.js: $("$NODE" -v)"

# ---- 2. Bot のファイル -----------------------------------------------------
TMP="$(mktemp -d)"
cat > "$TMP/bundle.json" <<'MAYO_BUNDLE_EOF'
{
"package-lock.json":"",
"package.json":"",
"src/commands.js":"",
"src/features/members.js":"",
"src/features/mod.js":"",
"src/features/modlog.js":"",
"src/features/msglog.js":"",
"src/features/recruit.js":"",
"src/features/rolepanel.js":"",
"src/features/setup.js":"",
"src/features/tickets.js":"",
"src/index.js":"",
"src/invite.js":"",
"src/recruit-core.js":"",
"src/store.js":"",
"src/time.js":"",
"src/transcript.js":"",
"src/util.js":""
}
MAYO_BUNDLE_EOF
GOT="$(sha256sum "$TMP/bundle.json" | cut -d' ' -f1)"
[ "$GOT" = "$BUNDLE_SHA256" ] || die "スクリプトが途中で切れています（ダウンロードし直してください）"
cat > "$TMP/unpack.mjs" <<'MAYO_UNPACK_EOF'
import fs from "node:fs";
import path from "node:path";
const [bundleFile, outDir] = process.argv.slice(2);
const bundle = JSON.parse(fs.readFileSync(bundleFile, "utf8"));
const OK = /^(src\/[A-Za-z0-9_.\/-]+\.js|package\.json|package-lock\.json)$/;
let n = 0;
for (const [rel, b64] of Object.entries(bundle)) {
  if (!OK.test(rel) || rel.includes("..")) throw new Error("この名前のファイルは入れられません: " + rel);
  const p = path.join(outDir, rel);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, Buffer.from(b64, "base64"));
  n++;
}
console.log(n + " ファイル");
MAYO_UNPACK_EOF
mkdir -p "$APP" "$STATE" "$ETC"
rm -rf "$APP/app.new" && mkdir -p "$APP/app.new"
OUT="$("$NODE" "$TMP/unpack.mjs" "$TMP/bundle.json" "$APP/app.new" 2>&1)" || die "Bot のファイルを取り出せませんでした: $OUT"
say "Bot のファイル: $OUT"
rm -rf "$TMP"
say "ライブラリ（discord.js）を入れています…（1 分ほど）"
NPM="$(dirname "$NODE")/npm"
( cd "$APP/app.new" && PATH="$(dirname "$NODE"):$PATH" "$NPM" ci --omit=dev --no-audit --no-fund --loglevel=error >/dev/null 2>&1 ) \
  || ( cd "$APP/app.new" && PATH="$(dirname "$NODE"):$PATH" "$NPM" install --omit=dev --no-audit --no-fund --loglevel=error >/dev/null 2>&1 ) \
  || die "discord.js を入れられませんでした（インターネットにつながっているか確かめてください）"
rm -rf "$APP/app.old"
[ -d "$APP/app" ] && mv "$APP/app" "$APP/app.old"
mv "$APP/app.new" "$APP/app"
chmod -R a+rX "$APP"

# ---- 3. Bot のトークン（前に入れたものがあれば、そのまま使う）-----------------
old() { [ -f "$ETC/env" ] && sed -n "s/^$1=//p" "$ETC/env" | head -1; }
TOKEN="$(printf '%s' "${MAYO_BOT_TOKEN:-}" | tr -d '[:space:]')"
[ -n "$TOKEN" ] || TOKEN="$(old DISCORD_TOKEN)"
valid() { printf '%s' "$1" | grep -Eq '^[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{20,}$'; }
if ! valid "$TOKEN"; then
  [ -r /dev/tty ] || die "トークンを入れられません。MAYO_BOT_TOKEN=… を付けて実行してください"
  echo
  echo "---- Discord の Bot のトークンを用意してください ----"
  echo " 1. https://discord.com/developers/applications →「New Application」で Bot を作る（名前は自由）"
  echo " 2. 左の「Bot」→「Reset Token」→ 出てきたトークンをコピー"
  echo " 3. 同じ「Bot」のページで、SERVER MEMBERS INTENT と MESSAGE CONTENT INTENT をオンにして「Save Changes」"
  echo "-----------------------------------------------------"
  for _ in 1 2 3; do
    printf '[mayo-bot] トークンを貼って Enter（画面には出ません）: ' > /dev/tty
    IFS= read -rs TOKEN < /dev/tty || TOKEN=""
    echo > /dev/tty
    TOKEN="$(printf '%s' "$TOKEN" | tr -d '[:space:]')"
    valid "$TOKEN" && break
    say "トークンの形がちがいます。もう一度コピーしてください"
    TOKEN=""
  done
  valid "$TOKEN" || die "トークンを入れられませんでした。もう一度実行してください"
fi
umask 077
cat > "$ETC/env" <<EOF
# まよ鯖 Bot の設定 … mayo-bot-setup.sh が作ります。トークンは人に見せないでください
DISCORD_TOKEN=$TOKEN
EOF
umask 022

if [ -n "$ROOT" ]; then say "テストなので、ここで終わります（$APP）"; return 0; fi

# ---- 4. 動かす用のユーザーと、自動で起動する設定（systemd）---------------------
id "$SVC" >/dev/null 2>&1 || useradd --system --no-create-home --home-dir /nonexistent --shell /usr/sbin/nologin "$SVC"
chown -R "$SVC:$SVC" "$STATE" && chmod 700 "$STATE"
cat > /etc/systemd/system/$SVC.service <<EOF
[Unit]
Description=まよ鯖 Bot（MaYo / mayo01297）
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$SVC
Group=$SVC
EnvironmentFile=$ETC/env
Environment=MAYO_BOT_DATA=$STATE
Environment=NODE_ENV=production
WorkingDirectory=$APP/app
ExecStart=$APP/node/bin/node --max-old-space-size=192 $APP/app/src/index.js
Restart=always
RestartSec=15
MemoryMax=350M
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
ReadWritePaths=$STATE

[Install]
WantedBy=multi-user.target
EOF

# ---- 5. mayo-bot コマンド ---------------------------------------------------
cat > /usr/local/bin/mayo-bot <<'EOF'
#!/bin/bash
# まよ鯖 Bot の操作（sudo mayo-bot …）制作: MaYo (mayo01297)
SVC=mayo-bot; APP=/opt/mayo-bot; ETC=/etc/mayo-bot; STATE=/var/lib/mayo-bot
URL="__UPDATE_URL__"
need_root() { [ "$(id -u)" = "0" ] || { echo "sudo を付けて実行してください（sudo mayo-bot $1）"; exit 1; }; }
case "${1:-}" in
  status)  systemctl --no-pager status $SVC | head -n 12; echo; journalctl -u $SVC -n 15 --no-pager -o cat ;;
  logs)    journalctl -u $SVC -n 100 -f -o cat ;;
  restart) need_root restart; systemctl restart $SVC && echo "再起動しました" ;;
  stop)    need_root stop; systemctl stop $SVC && echo "止めました（sudo mayo-bot start で動かします）" ;;
  start)   need_root start; systemctl start $SVC && echo "動かしました" ;;
  invite)  need_root invite; set -a; . $ETC/env; set +a; $APP/node/bin/node $APP/app/src/index.js --invite ;;
  token)
    need_root token
    printf 'Bot のトークンを貼って Enter（画面には出ません）: '; IFS= read -rs T; echo
    T="$(printf '%s' "$T" | tr -d '[:space:]')"
    printf '%s' "$T" | grep -Eq '^[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{20,}$' || { echo "トークンの形がちがいます"; exit 1; }
    ( umask 077; printf '# まよ鯖 Bot の設定\nDISCORD_TOKEN=%s\n' "$T" > $ETC/env )
    systemctl restart $SVC && echo "トークンを入れ直して、再起動しました" ;;
  backup)
    need_root backup
    F="$HOME/mayo-bot-backup-$(date +%Y%m%d-%H%M%S).json"
    cp $STATE/data.json "$F" && echo "保存しました: $F" ;;
  update)  need_root update; curl -fsSL "$URL" | bash ;;
  uninstall)
    need_root uninstall
    systemctl disable --now $SVC 2>/dev/null; rm -f /etc/systemd/system/$SVC.service; systemctl daemon-reload
    rm -rf $APP /usr/local/bin/mayo-bot
    if [ "${2:-}" = "--purge" ]; then rm -rf $ETC $STATE; echo "トークンとデータも消しました"; else echo "Bot を消しました（トークン: $ETC・データ: $STATE は残しています。消すときは --purge）"; fi ;;
  *)
    echo "まよ鯖 Bot の操作:"
    echo "  sudo mayo-bot status     … 動いているか・最近のログ"
    echo "  sudo mayo-bot logs       … ログを流して見る（Ctrl+C で止める）"
    echo "  sudo mayo-bot restart    … 再起動"
    echo "  sudo mayo-bot invite     … サーバーに入れる招待リンク"
    echo "  sudo mayo-bot token      … トークンを入れ直す"
    echo "  sudo mayo-bot backup     … データ（設定・パネル・募集）をコピー"
    echo "  sudo mayo-bot update     … 新しい版にする"
    echo "  sudo mayo-bot stop / start / uninstall" ;;
esac
EOF
sed -i "s#__UPDATE_URL__#$UPDATE_URL#" /usr/local/bin/mayo-bot
chmod 755 /usr/local/bin/mayo-bot

systemctl daemon-reload
systemctl enable $SVC >/dev/null 2>&1
systemctl restart $SVC || die "Bot を起動できませんでした（sudo mayo-bot status で確かめてください）"

# ---- 6. ログインできたか確かめる -----------------------------------------------
say "ログインできるか確かめています…"
OK=""
for _ in $(seq 1 30); do
  sleep 1
  LOG="$(journalctl -u $SVC -n 50 --no-pager -o cat 2>/dev/null)"
  if printf '%s' "$LOG" | grep -q '\[ready\]'; then OK=1; break; fi
  if printf '%s' "$LOG" | grep -q '\[login\]'; then break; fi
done
INVITE="$(set -a; . "$ETC/env"; set +a; "$APP/node/bin/node" "$APP/app/src/index.js" --invite 2>/dev/null)"
echo
echo "=================================================="
if [ -n "$OK" ]; then
  echo " ✅ まよ鯖 Bot が動きました！"
else
  echo " ⚠️ まだログインできていません。ログ:"
  printf '%s\n' "$LOG" | grep -E '\[login\]|Error' | tail -n 3
  echo "   トークンが正しいか・Developer Portal で 2 つの INTENT をオンにしたか確かめて、"
  echo "   sudo mayo-bot token（トークンを入れ直す）か sudo mayo-bot restart"
fi
echo
echo " 1. この招待リンクをブラウザでひらいて、まよ鯖に Bot を入れる:"
echo "    $INVITE"
echo " 2. サーバー設定 →「ロール」で、Bot のロールを、パネルで配るロールより上に動かす"
echo " 3. Discord で /設定 確認 → /設定 ログ・/設定 チケット などを設定（/ヘルプ で使い方）"
echo
echo " 操作: sudo mayo-bot（status / logs / restart / token / update …）"
echo "=================================================="
}

main "$@"
